import type { BookChapter } from "../types";

/* The Discover book — topic 1.4 (Research Solution Options) */
export const chapter4: BookChapter = {
  id: "day-4", n: "4", day: 4, title: "Research Solution Options", kicker: "Options Review",
  question: "What are the realistic ways to solve it — and do they work?",
  intro: [
    { t: "p", text: "Now, and only now, you look at solutions. Not one — all the realistic ways to solve the problem you stated in the previous topic: things you could buy, open source you could adopt, platform features you might already have, building it yourself, and doing nothing. Then you narrow them down with evidence, prove the riskiest part with a throwaway prototype, and sketch the survivors as real architectures." },
    { t: "p", text: "The order matters. For three topics you have kept solutions out of the room on purpose: you read the brief, audited the system, framed the problem without naming a tool, and measured what actually goes wrong. That discipline pays off here. Because the technical problem statement names no technology, every route gets a fair hearing — and because it carries numbers and hard constraints, every route can be tested against the same yardstick." },
    { t: "figure", fig: { kind: "flow", steps: [{ label: "Read the brief", sub: "topic 1.1" }, { label: "Audit the system", sub: "topic 1.1" }, { label: "Frame the problem", sub: "no tool named" }, { label: "Measure what goes wrong", sub: "topic 1.3" }, { label: "Look at solutions", sub: "topic 1.4", tone: "new" }] }, caption: "Three topics of keeping solutions out of the room, then this one. Because the problem statement names no technology, every route gets a fair hearing." },
    { t: "p", text: "This topic’s goal is simple to say and hard to fake: **find and prove the realistic ways to solve the technical problem before choosing one.** Notice the last three words. You don’t choose here. Choosing — with feasibility, effort and risk on the table — is topic 1.5. Here you make sure the choice, when it comes, is between real options that have been looked at honestly." },
    { t: "h", text: "How the four lessons chain" },
    { t: "p", text: "Each lesson narrows the field and hands a sharper artefact to the next. The scan casts the net wide; the evaluation scores the shortlist against the targets; the prototypes test the one thing the scores can’t settle; the sketches turn the survivors into architectures you can put side by side." },
    { t: "figure", fig: { kind: "funnel", stages: [{ label: "Scan", items: ["Cast the net wide", "Technology scan (OPT-##)"] }, { label: "Evaluate", items: ["Score the shortlist against the targets", "Option evaluation matrix"] }, { label: "Prototype", items: ["Test what the scores can’t settle", "Spike results (SPK-##)"] }, { label: "Sketch", items: ["Survivors as architectures", "Architecture options (ARO-##)"] }] }, caption: "Each lesson narrows the field and hands a sharper artefact to the next. Notice that nothing is chosen at the bottom — that is topic 1.5." },
    {
      t: "table", caption: "Topic 1.4 at a glance — what each lesson takes in and hands on",
      head: ["Lesson", "Starts from", "Produces", "Timebox"],
      rows: [
        ["1.4.1 Scan Existing Solutions & Technology", "Technical problem statement, technical constraint log", "Technology scan with a shortlist (OPT-##)", "½–1 day"],
        ["1.4.2 Evaluate Libraries, APIs & Services", "Technology scan, quality attribute priorities", "Option evaluation matrix — weighted, evidenced", "½–1 day"],
        ["1.4.3 Prototype the Riskiest Unknowns", "Spike plan, option evaluation matrix", "Spike results (SPK-## closing H-##)", "1–3 days"],
        ["1.4.4 Sketch Architecture Options", "Spike results, evaluation matrix, system context diagram", "Two or three architecture options (ARO-##)", "½–1 day"],
      ],
    },
    { t: "figure", fig: { kind: "trace", from: "QA", to: "ARO" }, caption: "Where this topic sits on the trace: the targets and spikes you framed earlier flow through the problem statement into options (OPT) and architecture options (ARO)." },
    { t: "h", text: "What passes the gate" },
    { t: "p", text: "The topic closes at the **Options Review**: buy, open-source and build routes were all considered, the weights were set before scoring, the spike signals were set in advance, and every option traces back to the targets." },
    { t: "p", text: "Each of those four checks guards against a specific way that option research goes wrong — looking only where you expected to look, scoring your favourite up, reading a borderline result generously, and drawing an architecture that is attractive but doesn’t answer the problem. If you can tick all four honestly, topic 1.5 starts from evidence rather than enthusiasm." },
    { t: "figure", fig: { kind: "tree", root: "Options Review", children: [{ label: "All routes considered", text: "Buy, open-source and build — guards against looking only where you expected to look." }, { label: "Weights set before scoring", text: "Guards against scoring your favourite up." }, { label: "Spike signals set in advance", text: "Guards against reading a borderline result generously." }, { label: "Every option traces to the targets", text: "Guards against an attractive architecture that doesn’t answer the problem." }] }, caption: "The gate’s four checks, each paired with the way of going wrong it guards against. Tick all four honestly and topic 1.5 starts from evidence." },
  ],
  sections: [
    /* ───────────────────────────── 1.4.1 ───────────────────────────── */
    {
      id: "discover.validate.scan", fid: "discover.validate.scan", code: "1.4.1", title: "Scan Existing Solutions & Technology", minutes: 13,
      blocks: [
        { t: "lead", text: "The most expensive software is the software you didn’t need to write. Before anyone builds anything, find every way the problem is already solved — products, open-source libraries, features of platforms you already pay for — and, always, the option of doing nothing." },
        { t: "tldr", items: [
          "List candidates across every route: buy, open source, platform feature, build, improve what’s there, and do nothing.",
          "Check each against the problem statement and the hard constraints first — a perfect product that breaks a hard constraint is not an option.",
          "Record fit, maturity, licence and cost band for every candidate, with sources.",
          "Agree a shortlist of two or three genuinely different routes, plus “do nothing”. The tech lead agrees it.",
        ] },
        { t: "p", text: "The job: *help me avoid building what I could adopt, and adopt only what really fits.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Engineers like building things. That is mostly a virtue, but at this point in discovery it is a risk. Left alone, a team will often reach for the approach it knows best and start designing — and only months later discover that a mature product, a well-kept library, or a feature hiding in a platform the client already pays for would have done most of the job." },
        { t: "p", text: "The opposite failure is just as real. A team adopts a product because it looked right in a demo, then finds it can’t keep data in the right region, can’t talk to the system it has to talk to, or carries a licence nobody read. Adopting the wrong thing is not cheaper than building the right thing; it is often more expensive, because leaving is hard." },
        { t: "figure", fig: { kind: "split", left: { title: "Build what you could adopt", tone: "bad", items: ["Reach for the approach you know best", "Start designing straight away", "Months later find a product, library or platform feature did most of it"] }, right: { title: "Adopt what doesn’t fit", tone: "bad", items: ["Chosen because it looked right in a demo", "Can’t keep data in the right region", "Can’t talk to the system it must", "A licence nobody read — and leaving is hard"] } }, caption: "The two failures the scan protects you from. Neither is cheaper than the other; adopting the wrong thing is often the more expensive." },
        { t: "p", text: "The scan protects you from both. It forces you to look across every route before you commit to any, and it forces every candidate through the same checks — fit, maturity, licence, cost — so that the shortlist is a fair one. It is also cheap: half a day to a day, most of it reading." },
        { t: "pull", text: "Don’t build what you can buy — unless it fails a hard constraint." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the first lesson of topic 1.4 and the first moment in Discover where solutions are allowed in. It starts from the **technical problem statement** you wrote at the end of topic 1.3 and the **technical constraint log** from topic 1.1. It produces the **technology scan**, and its shortlist goes straight into 1.4.2, where the options are scored." },
        {
          t: "table", caption: "The lesson’s contract in brief",
          head: ["", "What it is"],
          rows: [
            ["Entry", "Technical problem statement accepted"],
            ["Inputs", "Technical problem statement; technical constraint log"],
            ["Output", "Technology scan — every candidate with fit, maturity, licence and cost band, and a shortlist"],
            ["Exit", "At least one buy, one open-source and one build route considered; shortlist agreed"],
            ["Roles", "A — Tech lead · R — Engineer · C — Architect, Procurement · I — Client contact"],
            ["Authority", "Tech lead agrees the shortlist; procurement and legal review commercial terms"],
            ["Timebox", "½–1 day"],
            ["Trace", "Creates OPT-## linked to TPS-##"],
          ],
        },
        { t: "p", text: "The state of each candidate moves in one direction: **Unknown → Listed → Checked → Shortlisted.** Candidates can be researched in parallel — this is a good place to split work across people, or across several agent sessions." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Unknown" }, { label: "Listed", sub: "OPT ID + route" }, { label: "Checked", sub: "fit, maturity, licence, cost" }, { label: "Shortlisted", sub: "tech lead agrees", tone: "new" }] }, caption: "A candidate’s state only moves one way. Candidates can be researched in parallel — across people or agent sessions." },

        { t: "h", text: "What you start with" },
        { t: "p", text: "Two documents set the terms for every candidate. The problem statement says what a solution must achieve — in Northwind’s case, get at least 98% of lines into the ERP correctly without re-keying, lose no orders, and keep the median time under five minutes at peak. The constraint log says what no solution may break." },
        { t: "p", text: "Read the constraint log before you open a single product page. The hard constraints are your first filter and the fastest one: a candidate that breaks one is out, however good it looks. Soft constraints and assumptions are different — they shape the comparison but don’t eliminate anything on their own." },
        {
          t: "table", caption: "Northwind’s constraint log — the filter every candidate meets first",
          head: ["ID", "Statement", "Hard / soft", "Confidence"],
          rows: [
            ["C-01", "Orders enter the ERP only through its REST import API", "Hard", "High"],
            ["C-02", "Customer data stays in the EU", "Hard", "High"],
            ["A-01", "80% of order PDFs are machine-generated, not scans", "Soft (assumption)", "Low"],
          ],
        },
        { t: "figure", fig: { kind: "split", left: { title: "Hard constraints — filter", tone: "fact", items: ["Break one and the candidate is out", "C-01: orders enter the ERP only through its REST import API", "C-02: customer data stays in the EU"] }, right: { title: "Soft constraints and assumptions — shape", tone: "guess", items: ["Shape the comparison", "Don’t eliminate anything on their own", "A-01: 80% of order PDFs are machine-generated (low confidence)"] } }, caption: "Read the constraint log before any product page. Hard constraints remove candidates; soft ones and assumptions only weigh in — and A-01 comes back in 1.4.3." },
        { t: "note", text: "A-01 matters more than it looks. If many orders are scans, a candidate that reads generated PDFs well but scans badly may still fail the problem. Keep it in mind — it comes back in 1.4.3." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Six routes, not one" },
        { t: "p", text: "The technology scan has a route column with six values, and the habit to build is to fill every one of them before you judge any. **Buy** — a commercial product or service. **Open source** — a library or tool you adopt and run. **Platform feature** — something the client already licenses that might do the job. **Build** — writing it yourself. **Improve existing** — making what’s already there work better. **Do nothing** — leaving things as they are, with the cost written down." },
        { t: "figure", fig: { kind: "hub", center: "Six routes", items: [{ label: "Buy", icon: "shopping_cart", text: "A commercial product or service." }, { label: "Open source", icon: "code", text: "A library or tool you adopt and run." }, { label: "Platform feature", icon: "layers", text: "Something the client already licenses that might do the job." }, { label: "Build", icon: "construction", text: "Writing it yourself." }, { label: "Improve existing", icon: "build", text: "Making what’s already there work better." }, { label: "Do nothing", icon: "do_not_disturb_on", text: "Leaving things as they are, with the cost written down." }] }, caption: "Fill every route before you judge any. The exit needs at least one buy, one open-source and one build route." },
        { t: "p", text: "The exit criterion is explicit: at least one buy, one open-source and one build route must be considered. You can’t pass by listing three competing products from the same category." },
        { t: "figure", fig: { kind: "knowledge", name: "Build / buy / partner" }, caption: "Build, buy or partner — three routes, compared on the same terms." },
        { t: "h3", text: "Always include “do nothing”" },
        { t: "p", text: "“Do nothing” is not a joke entry. It is the honest baseline every option must beat, and it has a real cost — in Northwind’s case, clerk time. Writing it down stops a team from comparing options only against each other, when the real question is whether any of them is better than today. Sometimes, once the numbers are in, it wins." },
        { t: "h3", text: "Fit before features" },
        { t: "p", text: "A product’s feature list tells you what it can do. Fit asks whether it does **what your problem statement needs, within your constraints**. Mark each candidate yes, no or unknown against the hard constraints, and give the reason. “Unknown” is an honest and useful answer: it tells 1.4.2 exactly what to test." },
        { t: "h3", text: "Maturity, licence and cost band" },
        { t: "p", text: "**Maturity** asks who maintains it, how widely it is used and how active it is — mature, growing or early. **Licence** asks what you’re allowed to do with it: permissive open-source licences such as MIT or Apache-2.0 impose few obligations; copyleft licences such as the GPL family can oblige you to share source in some circumstances; commercial licences come with terms that procurement and legal need to read. **Cost band** is deliberately rough — free, €, €€, €€€ — because the real estimate comes in topic 1.5." },
        { t: "figure", fig: { kind: "tree", root: "What every candidate records", children: [{ label: "Maturity", text: "Who maintains it, how widely used, how active.", children: [{ label: "Mature" }, { label: "Growing" }, { label: "Early" }] }, { label: "Licence", text: "What you’re allowed to do with it — checked before any code is used.", children: [{ label: "Permissive", text: "MIT, Apache-2.0: few obligations" }, { label: "Copyleft", text: "GPL family: may oblige you to share source" }, { label: "Commercial", text: "Terms for procurement and legal" }] }, { label: "Cost band", text: "Deliberately rough; real estimates come in topic 1.5.", children: [{ label: "Free" }, { label: "€" }, { label: "€€" }, { label: "€€€" }] }] }, caption: "The three columns beside fit, and the values each can take. Licence is the one that is expensive to get wrong late." },
        { t: "p", text: "The policy here is firm: **licences are checked before any code is used.** A licence problem found after the code is in the product is expensive to undo." },
        { t: "h3", text: "Lock-in and exit cost" },
        { t: "p", text: "When only commercial options exist, you can still proceed — but note the lock-in and the cost of leaving. How would you get your data out? What would you have to rewrite? Lock-in isn’t automatically bad; it is a price, and the scan’s job is to make the price visible." },
        { t: "figure", fig: { kind: "knowledge", name: "Technology radar" }, caption: "A technology radar sorts tools into rings such as adopt, trial, assess and hold — a useful habit for remembering what your team already trusts, and what it has already ruled out." },
        {
          t: "terms", items: [
            { term: "Technology scan", def: "The list of every candidate solution, across all routes, with fit, maturity, licence, cost band and a shortlist mark." },
            { term: "Route", def: "The kind of solution: buy, open source, platform feature, build, improve existing or do nothing." },
            { term: "Hard constraint", def: "A limit no solution may break, confirmed by its owner — for example, “customer data stays in the EU”." },
            { term: "Cost band", def: "A rough cost class (free, €, €€, €€€) used for comparison before real estimates exist." },
            { term: "Software composition analysis", def: "Inventorying the third-party and open-source components a solution depends on, with their licences and known vulnerabilities." },
            { term: "Lock-in", def: "How hard and costly it would be to leave a product once you depend on it." },
          ],
        },

        { t: "h", text: "How to do it" },
        {
          t: "steps", items: [
            { title: "List the candidate solutions", text: "Starting from the problem statement, list every existing way to solve it: commercial products, open-source libraries, features of platforms the client already has, improving what’s there, building it, and doing nothing. Give each an OPT ID and fill the route column. Don’t judge yet — the point of this step is breadth. If you only list what the first search returns, you will miss the platform feature nobody mentioned.", tip: "If a platform feature already does the job, shortlist it first. It is usually the cheapest route to run and the easiest to support." },
            { title: "Check fit against the problem and the constraints", text: "Take each candidate through the hard constraints first — data region, interfaces, authentication — then against the problem statement. Mark fit as yes, no or unknown, with a one-line reason. A candidate that clearly fails a hard constraint is dropped, and the reason is written down so nobody re-proposes it next week.", tip: "“Unknown” is a finding, not a failure. Write down what would turn it into yes or no." },
            { title: "Check maturity, licence and cost", text: "For each candidate that fits or might fit, record maturity, licence and cost band — with sources. Use the vendor’s or project’s own pages, release history and licence file, not a blog post. Flag any licence that needs legal review, and any commercial terms for procurement. If a licence is unclear, mark it and ask; don’t shortlist it on hope.", tip: "AI services deserve extra care here: check them on accuracy claims you can test, not on marketing." },
            { title: "Agree the shortlist", text: "Propose two or three genuinely different routes plus “do nothing”, with a sentence on why each made it and why the others didn’t. The tech lead reviews and agrees the shortlist; that review is the evidence the lesson leaves behind. If the shortlist is three variants of the same idea, it isn’t a shortlist — go back and scan again." },
          ],
        },
        { t: "figure", fig: { kind: "workflow", fid: "discover.validate.scan" }, caption: "Scan Existing Solutions & Technology — list, check fit, check maturity, licence and cost, agree the shortlist; gaps loop back, licence questions go to legal." },

        { t: "h", text: "The case: Northwind" },
        { t: "callout", tone: "case", title: "Northwind", text: "A cloud document-AI service (EU region), open-source OCR plus rules, Vendor X’s connector and do nothing. Vendor X can’t confirm ERP v9 support." },
        { t: "p", text: "Northwind’s scan is short, and that is fine — what matters is that it spans the routes. There is a buy option that does the extraction for you, an open-source option you would run yourself, a commercial add-on that promises the whole e-mail-to-ERP path, and the honest baseline." },
        {
          t: "table", caption: "Northwind’s technology scan (TPS-01)",
          head: ["ID", "Option", "Route", "Fits hard constraints?", "Maturity", "Licence", "Cost band", "Shortlist"],
          rows: [
            ["OPT-1", "Cloud document-AI service (EU region)", "Buy", "Yes", "Mature", "Commercial, per page", "€€", "Yes"],
            ["OPT-2", "Open-source OCR + rules", "Open source", "Yes", "Mature", "Apache-2.0", "Free", "Yes"],
            ["OPT-3", "Vendor X ERP connector", "Buy", "Unknown", "Growing", "Commercial", "€€€", "No"],
            ["OPT-0", "Do nothing", "Do nothing", "Yes", "—", "—", "Clerk time", "Yes"],
          ],
        },
        { t: "figure", fig: { kind: "funnel", stages: [{ label: "Listed", count: 4, items: ["OPT-1 Cloud document-AI (EU)", "OPT-2 Open-source OCR + rules", "OPT-3 Vendor X ERP connector", "OPT-0 Do nothing"] }, { label: "Fits hard constraints", count: 3, items: ["OPT-1", "OPT-2", "OPT-0", "OPT-3: unknown — ERP v9 support unconfirmed"] }, { label: "Shortlisted", count: 3, items: ["OPT-1 (buy)", "OPT-2 (open source)", "OPT-0 (do nothing)"] }] }, caption: "Northwind’s scan narrowing to its shortlist. OPT-3 stays in the scan with its reason, but fit is unknown on C-01, so it doesn’t go forward." },
        { t: "p", text: "Look at OPT-3. On paper it is the most complete answer — an add-on that goes straight from e-mail to the ERP. But Vendor X can’t confirm it supports ERP v9, and C-01 says orders enter the ERP only through its import API. Fit is **unknown** on a hard constraint, the cost band is the highest on the list, and the product is still growing. It stays in the scan, with its reason, but it doesn’t make the shortlist." },
        { t: "p", text: "Look at OPT-1 too. A cloud service would normally raise an immediate question about C-02, but the scan records an EU region — so it fits, and the data-protection paperwork becomes something to confirm later rather than a reason to drop it now." },
        { t: "figure", fig: { kind: "template", id: "technology-scan" }, caption: "The technology scan — every candidate with fit, maturity, licence and cost band." },
        { t: "note", text: "At the end of Discover, Northwind’s learning log records exactly this lesson: check vendor support for the client’s ERP version in the first scan. It is cheaper to ask in topic 1.4 than to find out later." },

        { t: "h", text: "Working with your agent" },
        { t: "callout", tone: "agent", title: "With your agent", text: "Agents can survey the landscape in minutes. Ask for candidates across every route, each with licence and maintenance activity — then verify the claims that matter on the vendor’s or project’s own pages. Agents can be out of date, or confidently wrong about licences." },
        { t: "p", text: "Use the agent for breadth and for the tedious columns. Keep the judgement — fit, the shortlist, what counts as a hard-constraint failure — for yourself and the tech lead. Give the agent your problem statement and constraint log so it is checking against your limits, not generic ones." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Share problem statement and constraint log" }, { lane: 1, label: "List candidates across every route", sub: "fit, maturity, licence, cost — sources cited" }, { lane: 0, label: "Verify claims on vendor or project pages", flag: "manual" }, { lane: 0, label: "Judge fit and propose the shortlist" }, { lane: 1, label: "Challenge the shortlist", sub: "gaps, variants, unclear licences" }, { lane: 0, label: "Decide the shortlist" }, { lane: 2, label: "Review and agree the shortlist", flag: "ok" }] }, caption: "The agent brings breadth and fills the tedious columns; fit, the shortlist and what counts as a hard-constraint failure stay with you and the tech lead." },
        { t: "prompt", title: "Build the scan", text: "Here are my technical problem statement and my technical constraint log.\nList the existing ways to solve this problem across every route: commercial products, open-source libraries, features of platforms the client already has, improving what’s there, building it, and doing nothing.\nFor each candidate give: an OPT ID, the route, what it does for the problem statement, whether it fits each hard constraint (yes / no / unknown, with the reason), maturity, licence and a rough cost band.\nCite a source for every licence and maturity claim. Mark anything you aren’t sure of as unknown rather than guessing.\nFlag any licence or terms that need legal or procurement review." },
        { t: "p", text: "**What to check in the answer:** that every route appears, including “do nothing”; that each licence claim has a source you can open, and that the source says what the agent says; that “fits” really was checked against your hard constraints, not just the feature list; and that nothing marked “mature” is actually a project with one maintainer and no recent releases." },
        { t: "prompt", title: "Challenge the shortlist", text: "Here is my technology scan and the shortlist I’m proposing.\nCheck it: are these two or three genuinely different routes, or variants of the same idea? Is “do nothing” included with its cost? Is any candidate I dropped actually a better fit than one I kept? Is any shortlisted candidate unclear on licence or a hard constraint?\nGive me your reasons, but don’t change the shortlist — I decide." },
        { t: "p", text: "**What to check:** whether the agent found a real gap — a platform feature you missed, a route you skipped — or is simply proposing more products in the same category. Only the first sends you back to scan again." },

        { t: "h", text: "Common mistakes" },
        {
          t: "contrast", label: "Asking your agent for options",
          bad: { title: "Vague", text: "“What’s the best OCR library?” — one route, one category, no constraints, and an answer shaped by whatever is most written about." },
          good: { title: "Precise", text: "“Given this problem statement and these hard constraints (EU data, ERP import API only), list buy, open-source, platform, build and do-nothing options, each with fit, maturity, licence and cost band, sources cited.”" },
        },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "“Given this problem statement", label: "The problem", note: "So the agent checks against your goal, not a generic one." }, { text: " and these hard constraints (EU data, ERP import API only),", label: "Hard constraints", note: "Your limits, named." }, { text: " list buy, open-source, platform, build and do-nothing options,", label: "Every route", note: "Not one category." }, { text: " each with fit, maturity, licence and cost band,", label: "The scan’s columns" }, { text: " sources cited.”", label: "Evidence", note: "So you can verify what matters." }] }, caption: "The precise request, taken apart. Each part closes a gap the vague “best OCR library?” question leaves open." },
        {
          t: "pitfalls", items: [
            { trap: "Only the first search result is considered.", fix: "Require at least one buy, one open-source and one build route before anything is judged." },
            { trap: "The licence is ignored until the code is in use.", fix: "Check licences before shortlisting; mark unclear ones and ask." },
            { trap: "“Do nothing” is left out, so options are compared only with each other.", fix: "Add it with its real cost — the baseline every option must beat." },
            { trap: "A candidate that fails a hard constraint stays on the list because it demos well.", fix: "Drop it and write down which constraint it fails, so nobody brings it back." },
            { trap: "Lock-in is invisible because only commercial options were found.", fix: "Proceed, but note the lock-in and the cost of leaving next to each one." },
            { trap: "Agent claims about licences or maintenance are copied without checking.", fix: "Verify every claim that affects the shortlist on the vendor’s or project’s own pages." },
          ],
        },
        { t: "figure", fig: { kind: "fishbone", effect: "A scan you can’t trust", bones: [{ label: "Breadth", causes: ["Only the first search result considered", "Only commercial options found, lock-in invisible"] }, { label: "Licences", causes: ["Licence ignored until the code is in use", "Agent claims copied without checking"] }, { label: "Baseline", causes: ["“Do nothing” left out"] }, { label: "Constraints", causes: ["A candidate failing a hard constraint stays because it demos well"] }] }, caption: "The common mistakes grouped by where they come from. Each has a fix in the list above — most are about breadth and checking." },

        { t: "h", text: "When it goes off the path" },
        {
          t: "table", caption: "Routes out of the lesson",
          head: ["Situation", "What you do"],
          rows: [
            ["A platform feature already does it", "Shortlist it first"],
            ["There is an obvious single route", "Scan briefly anyway and record the alternatives you considered"],
            ["Research is thin, or the shortlist has gaps", "Scan again (rework)"],
            ["Licence unclear", "Mark it and ask before shortlisting"],
            ["Licence or vendor terms need legal", "Escalate through the tech lead"],
            ["Only commercial options exist", "Note the lock-in and exit cost, and continue"],
            ["Nothing fits the hard constraints", "Stop: back to framing with the constraint that blocks — recorded in the learning log"],
          ],
        },
        { t: "figure", fig: { kind: "decide", start: "fit", nodes: [{ id: "fit", q: "Does any candidate fit the hard constraints?", yes: "platform", no: "stop" }, { id: "stop", result: "Stop: back to framing with the constraint that blocks — record it in the learning log.", tone: "bad" }, { id: "platform", q: "Does a platform feature already do it?", yes: "first", no: "legal" }, { id: "first", result: "Shortlist it first.", tone: "good" }, { id: "legal", q: "Do licence or vendor terms need legal?", yes: "esc", no: "unclear" }, { id: "esc", result: "Escalate through the tech lead.", tone: "neutral" }, { id: "unclear", q: "Is any licence unclear?", yes: "ask", no: "thin" }, { id: "ask", result: "Mark it and ask before shortlisting.", tone: "neutral" }, { id: "thin", q: "Is research thin, or does the shortlist have gaps?", yes: "rescan", no: "commercial" }, { id: "rescan", result: "Scan again (rework).", tone: "bad" }, { id: "commercial", q: "Do only commercial options exist?", yes: "lockin", no: "agree" }, { id: "lockin", result: "Note the lock-in and exit cost, and continue.", tone: "neutral" }, { id: "agree", result: "Propose the shortlist; the tech lead agrees it.", tone: "good" }] }, caption: "Walk the main routes out of the scan. “Nothing fits” is a result: it sends you back to framing with the blocking constraint." },
        { t: "callout", tone: "warn", title: "“Nothing fits” is a result, not a failure", text: "If every candidate breaks a hard constraint, that is important news. Go back to framing with the constraint that blocks, and record it. Pretending a candidate “nearly” fits only moves the problem into the build." },
        { t: "p", text: "Afterwards, one measure tells you whether the scan was good: **options found later that were missed.** If one turns up in week three, add it to the learning log — it will make the next scan better." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Buy, open-source, platform and build routes are all considered", "Every candidate has fit, maturity, licence and cost band", "“Do nothing” is included", "Options failing a hard constraint are dropped with the reason"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Scan done?", items: [
          "Every route has at least been looked at — buy, open source, platform feature, build, improve existing, do nothing",
          "Each candidate is checked against every hard constraint, with yes / no / unknown and a reason",
          "Fit, maturity, licence and cost band are filled for every candidate, with sources",
          "Unclear licences are marked and asked about; legal or procurement questions are raised",
          "The shortlist is two or three genuinely different routes plus “do nothing”",
          "The tech lead has reviewed and agreed the shortlist",
        ] },
        { t: "try", text: "Add “do nothing” and one open-source option to the order-intake technology scan. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.4.2 ───────────────────────────── */
    {
      id: "discover.validate.evaluate", fid: "discover.validate.evaluate", code: "1.4.2", title: "Evaluate Libraries, APIs & Services", minutes: 12,
      blocks: [
        { t: "lead", text: "Everyone has a favourite. This lesson judges the shortlist against the quality targets you agreed in topic 1.2 — not against preference — so whichever option wins, the choice can be defended." },
        { t: "tldr", items: [
          "Turn the ranked quality attributes and hard constraints into weighted criteria — and fix the weights before you look at any option.",
          "Try each option in a sandbox with the same test data, so scores come from evidence, not reputation.",
          "Score each option per criterion and cite the doc, test call or measurement behind every score.",
          "List the unknowns each option still carries; they become the prototype’s job.",
          "Weights are never changed after seeing scores.",
        ] },
        { t: "p", text: "The job: *help me compare options fairly, so the choice can be defended.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "By the time you have a shortlist, someone in the room usually has a favourite. It might be the option they used on their last project, the one with the best demo, or the one that feels most modern. None of that is evidence, and none of it will survive a hard question from the client — “why this one?” — six months from now." },
        { t: "p", text: "A fair evaluation does two things. It ties every criterion to something already agreed — the quality targets — so the comparison is about the problem, not taste. And it ties every score to something checkable — a document, a test call, a measurement — so anyone can re-read the matrix and reach the same view. That is what makes a choice defensible." },
        { t: "figure", fig: { kind: "tree", root: "A defensible choice", children: [{ label: "Criteria tied to the targets", text: "The comparison is about the problem, not taste.", children: [{ label: "QA-## scenarios" }, { label: "Hard constraints" }] }, { label: "Scores tied to evidence", text: "Anyone can re-read the matrix and reach the same view.", children: [{ label: "A document" }, { label: "A test call" }, { label: "A measurement" }] }, { label: "Unknowns listed", text: "What you still don’t know tells you what to prototype next." }] }, caption: "What a fair evaluation rests on. Take away either tie — to the targets or to evidence — and the choice won’t survive “why this one?”." },
        { t: "p", text: "It also shows you, honestly, what you still don’t know. The unknowns column is as valuable as the scores: it tells you what to prototype next." },
        { t: "pull", text: "If you change the weights after seeing the scores, you didn’t evaluate the options — you justified your favourite." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "The shortlist arrives from 1.4.1. The quality attribute priorities come from topic 1.2, where you ranked the attributes and wrote each as a measurable scenario. This lesson joins the two into an **option evaluation matrix**, which goes on to 1.4.3 — where the unknowns it surfaces are tested with prototypes." },
        {
          t: "table", caption: "The lesson’s contract in brief",
          head: ["", "What it is"],
          rows: [
            ["Entry", "Shortlist agreed"],
            ["Inputs", "Technology scan; quality attribute priorities; trial accounts or sandboxes"],
            ["Output", "Option evaluation matrix — weighted criteria, scores with evidence, unknowns per option"],
            ["Exit", "Every score cites evidence; remaining unknowns per option listed"],
            ["Roles", "A — Tech lead · R — Engineer · C — Architect, Security · I — Procurement"],
            ["Authority", "Tech lead accepts the evaluation"],
            ["Policy", "Trials use test data only"],
            ["Timebox", "½–1 day"],
            ["Trace", "Scores link to QA-## and OPT-##"],
          ],
        },
        { t: "p", text: "Each option moves **Shortlisted → Tried → Scored → Reviewed**, and options can be evaluated in parallel." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Shortlisted" }, { label: "Tried", sub: "sandbox, same sample" }, { label: "Scored", sub: "evidence per score" }, { label: "Reviewed", sub: "tech lead accepts", tone: "new" }] }, caption: "Each option’s path through the lesson. Options can be evaluated in parallel, but always on the same test data." },

        { t: "h", text: "What you start with" },
        { t: "p", text: "You need the shortlist and the targets. For Northwind, the targets are three ranked quality-attribute scenarios — each written as “when… the system… measured as…”, so each can be tested." },
        {
          t: "table", caption: "Northwind’s quality attribute priorities — where the criteria come from",
          head: ["QA", "Attribute", "Rank", "Scenario"],
          rows: [
            ["QA-1", "Functional correctness", "1", "When a generated or scanned PDF order arrives, the system creates the ERP order with ≥ 98% of lines correct; anything below confidence goes to a clerk."],
            ["QA-2", "Reliability", "2", "When the ERP API is down, no order is lost; all are retried within 15 min of recovery."],
            ["QA-3", "Performance efficiency", "3", "At peak (≈160 orders/h) median e-mail-to-ERP time stays under 5 min."],
          ],
        },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "When the ERP API is down,", label: "When", note: "The situation that tests the attribute." }, { text: " no order is lost;", label: "The system", note: "What it must do — QA-2, reliability." }, { text: " all are retried within 15 min of recovery.", label: "Measured as", note: "The number a sandbox test or spike can check." }] }, caption: "QA-2 taken apart. Because each scenario is written “when… the system… measured as…”, each one can become a criterion and be tested." },
        { t: "p", text: "You also need somewhere to try each option: a sandbox, a free tier, a trial account or a local install. And you need test data — masked or synthetic, never real customer data in a vendor trial." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Criteria come from the targets" },
        { t: "p", text: "Every criterion in the matrix should point at a QA-## or a hard constraint. “Developer experience” or “modern” might matter to the team, but if it isn’t in the targets, it isn’t a criterion. This is the core of **Attribute-Driven Design**: the quality attributes, written as scenarios, drive the design decisions — including which components to adopt." },
        { t: "figure", fig: { kind: "knowledge", name: "Weighted scoring" }, caption: "Weighted scoring: criteria from the targets, weights set first, scores with evidence." },
        { t: "h3", text: "Weights first, then scores" },
        { t: "p", text: "The ranking you made in topic 1.2 becomes the weights. Set them now, before you look at any option, and record them where they can’t quietly move. The arithmetic is simple — for each option, multiply each score by its criterion’s weight and add them up — but the order is everything. Weights chosen after the scores are visible can be bent, consciously or not, to produce whichever winner someone already wanted." },
        { t: "figure", fig: { kind: "split", left: { title: "Weights first", tone: "good", items: ["Set from the topic 1.2 ranking", "Recorded before any option is opened", "Kept where they can’t quietly move", "Scores then decide the winner"] }, right: { title: "Weights after the scores", tone: "bad", items: ["Set with the scores visible", "Bent, consciously or not", "Produce whichever winner someone already wanted", "You justified your favourite"] } }, caption: "The arithmetic is the same either way; the order is everything." },
        { t: "p", text: "Hard constraints need a decision too. Some teams treat them only as a pass/fail gate before scoring; others also score how well each option meets them. Either is fine, as long as you decide before scoring and an option that fails a hard constraint is dropped, not just marked down." },
        { t: "h3", text: "Evidence over assertion" },
        { t: "p", text: "A score is only as good as what stands behind it. Acceptable evidence is a document you can cite, a test call you made, or a measurement you took. Marketing pages are not evidence — they are claims. If an option has no sandbox, you can score from its documentation, but mark the score as lower confidence so nobody mistakes it for a measurement." },
        { t: "figure", fig: { kind: "stack", layers: [{ label: "A test call or a measurement", sub: "Evidence you produced in the sandbox" }, { label: "A document you can cite", sub: "Acceptable; with no sandbox, mark the score lower confidence" }, { label: "Marketing pages", sub: "Claims, not evidence" }] }, caption: "What can stand behind a score, strongest first. A score from documentation alone must say so, so nobody mistakes it for a measurement." },
        { t: "h3", text: "Test calls, contracts and fitness functions" },
        { t: "p", text: "Two ideas from everyday engineering help here. **Contract testing** asks whether an API actually behaves as its documentation says — the fields, the errors, the authentication. **Fitness functions** are objective checks of an architectural characteristic, such as “a page is processed in under so many seconds” or “accuracy on this sample is at least so much”. A quick sandbox test is often a fitness function in miniature: one criterion, one number, repeatable." },
        { t: "h3", text: "Same sample, every option" },
        { t: "p", text: "Run every option against the same test data. If one option is tried on clean generated PDFs and another on messy scans, the scores compare the samples, not the options. Real calls, real timings, accuracy on your own documents — and auth and data handling checked in the sandbox while you’re there." },
        {
          t: "terms", items: [
            { term: "Option evaluation matrix", def: "A table of criteria (from the quality attributes), their weights, each option’s score per criterion, the evidence for every score, and each option’s open unknowns." },
            { term: "Weight", def: "How much a criterion counts, set from the quality-attribute ranking before any option is scored." },
            { term: "Weighted score", def: "The sum of each criterion’s score multiplied by its weight." },
            { term: "Sandbox", def: "A trial environment — free tier, trial account or local install — where you can test an option without real data or production systems." },
            { term: "Fitness function", def: "An objective, repeatable check of an architectural characteristic, such as accuracy or latency on a fixed sample." },
            { term: "Contract testing", def: "Checking that an API behaves as its documented contract says it does." },
          ],
        },

        { t: "h", text: "How to do it" },
        {
          t: "steps", items: [
            { title: "Turn quality attributes into weighted criteria", text: "Take each ranked quality attribute and each hard constraint you want to score, and write it as a criterion with a reference — “Line accuracy (QA-1)”. Give each a weight that reflects the topic 1.2 ranking; the top-ranked attribute should carry the most. Fix the weights, record them, and only then open the shortlist. If you work in a spreadsheet, keep the weights in their own locked cells.", tip: "Write down, before scoring, what score 1 and score 5 mean for each criterion. It stops scores drifting between options." },
            { title: "Try each option in a sandbox", text: "For each shortlisted option, find the quickest test that produces evidence for each criterion: a test call, a sample run, a timing. Use masked or synthetic data and the same sample for every option. Check authentication and data handling while you’re in the sandbox. If a trial needs a contract signed, that goes to procurement — don’t sign anything yourself.", tip: "Read the docs first, then make the call. The docs tell you what should happen; the call tells you what does." },
            { title: "Score with evidence and list the unknowns", text: "Score each option per criterion — 1 to 5 is plenty — and cite the evidence next to every score: a document section, a test-call result, a measurement. Then, for each option, list what you still don’t know: behaviour on documents you didn’t test, limits you couldn’t reach in a trial, dependencies you couldn’t check. If an option fails a hard constraint, drop it and record why.", tip: "An unknown is not a low score. Keep them in separate columns so the matrix stays honest." },
            { title: "Decide: is the evaluation evidenced?", text: "The tech lead reviews the matrix. Every score must have evidence; the weights must be the ones recorded before scoring. Scores without evidence send you back to try again. If two options tie, the riskiest unknown decides — and that unknown becomes the prototype. If one option is a clear winner, its riskiest unknown is still prototyped next." },
          ],
        },
        { t: "figure", fig: { kind: "workflow", fid: "discover.validate.evaluate" }, caption: "Evaluate Libraries, APIs & Services — weighted criteria first, sandbox each option, score with evidence, then the tech lead checks it’s evidenced." },
        { t: "callout", tone: "warn", title: "Weights never move after scoring", text: "If you change the weights after seeing the scores, you didn’t evaluate the options — you justified your favourite." },

        { t: "h", text: "The case: Northwind" },
        { t: "callout", tone: "case", title: "Northwind", text: "Weights set first from QA-1–3; sandbox calls give document-AI 96% on generated PDFs and open-source OCR 93%." },
        { t: "p", text: "Two options reached the matrix: OPT-1, the cloud document-AI service, and OPT-2, open-source OCR with rules. (“Do nothing” is the baseline; it doesn’t need sandbox calls.) The weights follow the topic 1.2 ranking — correctness first, reliability second, latency third — with the EU-data constraint carried as a criterion too." },
        { t: "figure", fig: { kind: "bars", unit: "%", rows: [{ label: "Line accuracy (QA-1)", value: 40, max: 100, note: "40%", tone: "neutral" }, { label: "No lost orders (QA-2)", value: 25, max: 100, note: "25%", tone: "neutral" }, { label: "EU data (C-02)", value: 20, max: 100, note: "20%", tone: "neutral" }, { label: "Peak latency (QA-3)", value: 15, max: 100, note: "15%", tone: "neutral" }] }, caption: "The weights, fixed before any option was scored. Correctness — the top-ranked attribute — carries the most." },
        {
          t: "table", caption: "Northwind’s option evaluation (example rows from the matrix)",
          head: ["Criterion", "Weight", "OPT-1 score", "OPT-1 evidence", "OPT-2 score", "OPT-2 evidence"],
          rows: [
            ["Line accuracy (QA-1)", "40%", "4", "Trial on 50 PDFs: 96% generated, 88% scans", "3", "Trial: 93% generated, 71% scans"],
            ["No lost orders (QA-2)", "25%", "4", "Async API with retries", "4", "Runs in our queue"],
            ["Peak latency (QA-3)", "15%", "4", "~6 s a page (docs + trial)", "5", "~2 s a page locally"],
            ["EU data (C-02)", "20%", "5", "EU region, DPA available", "5", "Self-hosted"],
          ],
        },
        { t: "p", text: "Work the arithmetic and OPT-1 comes to 4.2 out of 5, OPT-2 to 3.95. That is close — and the closeness is the lesson. OPT-2 wins on latency and ties on reliability and EU data; OPT-1 wins on the criterion that carries the most weight. Change the weights and you could change the winner, which is exactly why they were fixed first." },
        { t: "figure", fig: { kind: "scorecard", criteria: [{ label: "Line accuracy (QA-1)", weight: 40 }, { label: "No lost orders (QA-2)", weight: 25 }, { label: "Peak latency (QA-3)", weight: 15 }, { label: "EU data (C-02)", weight: 20 }], options: [{ label: "OPT-1 Document-AI", scores: [4, 4, 4, 5] }, { label: "OPT-2 Open-source OCR", scores: [3, 4, 5, 5] }], scale: 5, note: "OPT-1 4.2, OPT-2 3.95 with the weights fixed first. Change the weights and you could change the winner." }, caption: "Northwind’s matrix, worked. Try moving the weights to see how easily the winner flips — which is exactly why they were fixed before scoring." },
        { t: "figure", fig: { kind: "bars", rows: [{ label: "Document-AI service · generated PDFs", value: 96, max: 100, note: "96%", tone: "good" }, { label: "Open-source OCR · generated PDFs", value: 93, max: 100, note: "93%", tone: "neutral" }] }, caption: "Sandbox evidence on generated PDFs. Both look close — which is why the riskiest case gets its own prototype next." },
        { t: "p", text: "The unknowns column is where the next lesson begins. A-01 — “most PDFs are generated, not scanned” — is still a low-confidence assumption, and scans are where the two options pull apart. That is the riskiest unknown, and it is already in the spike plan as SPK-1." },
        { t: "figure", fig: { kind: "template", id: "option-evaluation" }, caption: "The option evaluation matrix — criteria from the QAs, weights, and a score with evidence for every option." },

        { t: "h", text: "Working with your agent" },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to build the matrix and run the sandbox calls with the same sample for every option. Keep the weights in a separate, locked cell you set before it starts." },
        { t: "p", text: "An agent is good at reading long API documentation, writing the small scripts that make test calls, and tabulating results. It is not the right party to set the weights — they come from priorities people agreed — and it should never be the source of a score without evidence attached." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Share ranked QAs and hard constraints" }, { lane: 1, label: "Turn them into weighted criteria", sub: "no option looked at yet" }, { lane: 0, label: "Check and lock the weights", flag: "manual" }, { lane: 1, label: "Propose sandbox tests", sub: "same masked sample for every option" }, { lane: 0, label: "Run the tests and paste results" }, { lane: 1, label: "Score from that evidence only", sub: "cite every score; list unknowns" }, { lane: 0, label: "Trace every citation to a result" }, { lane: 2, label: "Review and accept the matrix", flag: "ok" }] }, caption: "The agent reads documentation, writes test calls and tabulates. The weights come from people, and no score enters without evidence attached." },
        { t: "prompt", title: "Weights, then test calls", text: "Here are my quality attribute priorities (ranked, with scenarios) and my hard constraints.\nTurn them into weighted criteria for an option evaluation matrix. Show the weights and how they follow the ranking. Don’t look at any option yet.\nThen, for each shortlisted option in this technology scan, propose the quickest sandbox test or test call that would give evidence for each criterion, using masked or synthetic data — the same sample for every option.\nTell me what each test measures and how I’d read the result." },
        { t: "p", text: "**What to check:** that each criterion points at a QA-## or a constraint; that the weights match your ranking and you are happy with them before you go further; that every test uses the same sample; and that no test sends real customer data to a vendor." },
        { t: "prompt", title: "Score from my evidence", text: "Here are the results of my sandbox tests, pasted in full, and the locked weights.\nScore each option 1–5 per criterion from this evidence only. Cite the evidence next to every score. Where there is no evidence, leave the score blank and say what test would provide it.\nList the unknowns each option still carries.\nDo not change the weights." },
        { t: "p", text: "**What to check:** every score has a citation you can trace to a result you pasted; no score quietly relies on the agent’s general knowledge of a product; the weights in the output are the ones you set; and the unknowns are specific enough to test." },

        { t: "h", text: "Common mistakes" },
        {
          t: "contrast", label: "A score in the matrix",
          bad: { title: "Assertion", text: "“Accuracy: 5 — it’s the market leader and the demo was excellent.”" },
          good: { title: "Evidence", text: "“Accuracy: 4 — trial on our masked sample: 96% of lines exact on generated PDFs. Scans not yet tested (unknown).”" },
        },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Accuracy: 4", label: "Score", note: "1–5 against what 1 and 5 were defined to mean." }, { text: " — trial on our masked sample:", label: "Source", note: "Your own data, the same for every option." }, { text: " 96% of lines exact on generated PDFs.", label: "Measurement" }, { text: " Scans not yet tested (unknown).", label: "Unknown", note: "Kept apart from the score — it feeds the prototype." }] }, caption: "An evidenced score, taken apart. Compare the assertion above: no source, no number, no unknown." },
        {
          t: "pitfalls", items: [
            { trap: "Weights are adjusted after the scores are visible.", fix: "Restore the original weights and re-score. Record the weights before opening any option." },
            { trap: "Marketing pages are used as evidence.", fix: "Replace them with documentation or a test call." },
            { trap: "Each option is tried on different data.", fix: "Use one masked or synthetic sample for every option." },
            { trap: "Criteria appear that aren’t in the targets — “modern”, “nice API”.", fix: "Every criterion points at a QA-## or a hard constraint, or it comes out." },
            { trap: "Unknowns are hidden inside low scores.", fix: "Keep a separate unknowns column per option; it feeds the prototype." },
            { trap: "Real customer data goes into a vendor trial.", fix: "Trials use test data only — masked or synthetic." },
          ],
        },
        { t: "figure", fig: { kind: "fishbone", effect: "A choice that can’t be defended", bones: [{ label: "Weights", causes: ["Adjusted after the scores are visible"] }, { label: "Evidence", causes: ["Marketing pages used as evidence", "Unknowns hidden inside low scores"] }, { label: "Data", causes: ["Each option tried on different data", "Real customer data in a vendor trial"] }, { label: "Criteria", causes: ["Criteria not in the targets — “modern”, “nice API”"] }] }, caption: "Where evaluations go wrong, grouped. Every cause either bends the comparison or breaks the policy that trials use test data only." },

        { t: "h", text: "When it goes off the path" },
        {
          t: "table", caption: "Routes out of the lesson",
          head: ["Situation", "What you do"],
          rows: [
            ["Two options tie", "The riskiest unknown decides — prototype it"],
            ["One clear winner", "Still prototype its riskiest unknown"],
            ["No sandbox available", "Score from docs and mark lower confidence"],
            ["An option fails a hard constraint", "Drop it, record why"],
            ["Scores without evidence", "Evaluate again (rework)"],
            ["The trial needs a contract", "Escalate to procurement"],
            ["No option meets the minimum targets", "Stop: back to framing — recorded in the learning log"],
          ],
        },
        { t: "figure", fig: { kind: "decide", start: "min", nodes: [{ id: "min", q: "Does any option meet the minimum targets?", yes: "contract", no: "stop" }, { id: "stop", result: "Stop: back to framing — record it in the learning log.", tone: "bad" }, { id: "contract", q: "Does the trial need a contract?", yes: "proc", no: "sandbox" }, { id: "proc", result: "Escalate to procurement — don’t sign anything yourself.", tone: "neutral" }, { id: "sandbox", q: "Is a sandbox available?", yes: "hard", no: "docs" }, { id: "docs", result: "Score from docs and mark it lower confidence.", tone: "neutral" }, { id: "hard", q: "Does an option fail a hard constraint?", yes: "drop", no: "evidence" }, { id: "drop", result: "Drop it and record why.", tone: "bad" }, { id: "evidence", q: "Does every score cite evidence?", yes: "tie", no: "rework" }, { id: "rework", result: "Evaluate again (rework).", tone: "bad" }, { id: "tie", q: "Do two options tie?", yes: "risky", no: "winner" }, { id: "risky", result: "The riskiest unknown decides — prototype it.", tone: "good" }, { id: "winner", result: "One clear winner: still prototype its riskiest unknown.", tone: "good" }] }, caption: "The routes out of the evaluation as a walk-through. Both good endings lead to the same place: a prototype of the riskiest unknown." },
        { t: "note", text: "The lesson’s measure is “scores with test-call evidence” — the more of the matrix that rests on calls you made rather than documents you read, the stronger it is. Note the criteria that decided it in the learning log." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Criteria and weights set before scoring", "Each score cites a doc, test call or measurement", "Every option lists the unknowns it still carries"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Evaluation evidenced?", items: [
          "Every criterion points at a QA-## or a hard constraint",
          "Weights were recorded before any option was scored, and haven’t moved",
          "Every option was tried on the same masked or synthetic sample",
          "Every score cites a document, test call or measurement",
          "Each option lists the unknowns it still carries",
          "Options failing a hard constraint are dropped with the reason",
          "The tech lead has reviewed and accepted the matrix",
        ] },
        { t: "try", text: "Set weights for three criteria before scoring any option. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.4.3 ───────────────────────────── */
    {
      id: "discover.validate.prototype", fid: "discover.validate.prototype", code: "1.4.3", title: "Prototype the Riskiest Unknowns", minutes: 12,
      blocks: [
        { t: "lead", text: "Some questions can’t be answered by reading or scoring. You have to build something small and see. This lesson takes the riskiest remaining unknown and turns it into evidence by building the smallest thing that could prove it wrong — the spikes you planned in topic 1.2." },
        { t: "tldr", items: [
          "Pick the unknown that could most change the decision — usually the one that could sink the favourite.",
          "Build the smallest throwaway prototype that could fail, on realistic, masked data, never against production.",
          "Read the result against the success signal you set in advance — and don’t move it.",
          "Write up each spike: question, approach, result with data, remaining unknowns, what it changes.",
          "Prototype code is throwaway. Timeboxes are respected.",
        ] },
        { t: "p", text: "The job: *help me know — not hope — that the risky part works before anyone commits to it.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "A matrix can tell you which option looks best on the evidence you have. It can’t tell you about the evidence you don’t have. Every option leaves 1.4.2 carrying unknowns, and one of them is usually big enough to overturn the whole comparison — the part of the problem nobody has actually tried." },
        { t: "p", text: "You can carry that unknown into the build and find out in month two, when changing course means rewriting. Or you can spend a day or two now, building the smallest possible thing that answers it. The second is almost always cheaper. That is the whole argument for a spike: **learn the most for the least.**" },
        { t: "figure", fig: { kind: "split", left: { title: "Carry the unknown into the build", tone: "bad", items: ["Find out in month two", "Changing course means rewriting"] }, right: { title: "Spike it now", tone: "good", items: ["A day or two", "The smallest thing that answers it", "Learn the most for the least"] } }, caption: "The whole argument for a spike. A spike that disproves the favourite is the best outcome — it saved a build that would have gone wrong." },
        { t: "p", text: "A spike that disproves the favourite is not a failure. It is the best outcome discovery can produce, because it saved a build that would have gone wrong." },
        { t: "pull", text: "Know, don’t hope: build the smallest thing that could prove you wrong." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "In topic 1.2 you turned your riskiest guesses into technical hypotheses (H-##) and planned a spike for each important one — with a timebox and a success signal set in advance. Here those spikes run. The evaluation matrix from 1.4.2 tells you which unknowns still matter most; the spike plan tells you how you agreed to test them. The results go on to 1.4.4, where only options that survived are sketched." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Hypotheses H-##", sub: "topic 1.2" }, { label: "Spike plan", sub: "timebox + signal, topic 1.2" }, { label: "Matrix unknowns", sub: "1.4.2" }, { label: "Spikes run", sub: "this topic", tone: "new" }, { label: "Survivors sketched", sub: "1.4.4" }] }, caption: "Where the spikes come from and where their results go. The matrix says which unknowns matter most; the plan says how you agreed to test them." },
        {
          t: "table", caption: "The lesson’s contract in brief",
          head: ["", "What it is"],
          rows: [
            ["Entry", "Evaluation matrix reviewed; spike plan approved"],
            ["Inputs", "Spike plan; option evaluation matrix; a test environment; masked sample data"],
            ["Output", "Spike results — question, approach, result with data, remaining unknowns, what it changes"],
            ["Exit", "Each spike answered within its timebox; results read against the signal set in advance"],
            ["Roles", "A — Tech lead · R — Engineer · C — Architect · I — Client contact"],
            ["Authority", "Tech lead reads the verdict; extending a timebox needs the tech lead"],
            ["Policy", "Never prototype against production"],
            ["Timebox", "1–3 days"],
            ["Trace", "Spike results close H-## via SPK-##"],
          ],
        },
        { t: "p", text: "Each unknown moves **Unknown → Prototyped → Measured → Answered.** Independent spikes can run in parallel — Northwind’s two spikes test different systems and don’t depend on each other." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Unknown" }, { label: "Prototyped" }, { label: "Measured" }, { label: "Answered", tone: "new" }] }, caption: "Each unknown’s path. Independent spikes — like Northwind’s two, which test different systems — run in parallel." },

        { t: "h", text: "What you start with" },
        { t: "p", text: "The spike plan is the contract you made with yourself in topic 1.2. Each row names the hypothesis, the smallest test, the timebox, the success signal, and the data or environment. The point of writing the signal down then was so that you can’t move it now." },
        {
          t: "table", caption: "Northwind’s spike plan — set in topic 1.2, before anyone saw a result",
          head: ["SPK", "Hypothesis", "Smallest test", "Timebox", "Success signal"],
          rows: [
            ["SPK-1", "H-01 OCR accuracy", "Run 2 OCR services over 200 masked inbox PDFs; compare to clerk-entered orders", "1 day", "≥ 95% of lines exact on generated, ≥ 85% on scans"],
            ["SPK-2", "H-02 ERP throughput", "Script 1,000 synthetic orders into the ERP test tenant", "½ day", "≥ 160 orders/h sustained, no errors"],
          ],
        },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "H-01 OCR accuracy:", label: "Hypothesis" }, { text: " run 2 OCR services over 200 masked inbox PDFs and compare to clerk-entered orders,", label: "Smallest test", note: "Realistic, masked data, checked against what clerks entered." }, { text: " within 1 day;", label: "Timebox" }, { text: " held if ≥ 95% of lines are exact on generated and ≥ 85% on scans.", label: "Success signal", note: "Written in topic 1.2, before anyone saw a result." }] }, caption: "SPK-1’s row in the spike plan, read as one sentence. The signal is the part you can’t move now." },
        { t: "figure", fig: { kind: "timeline", unit: "days", items: [{ label: "SPK-1 · H-01 OCR accuracy", start: 0, length: 1, tone: "risk" }, { label: "SPK-2 · H-02 ERP throughput", start: 0, length: 0.5, tone: "system" }] }, caption: "Northwind’s two timeboxes side by side. The spikes test different systems and don’t depend on each other, so they can run in parallel." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "A spike answers one question" },
        { t: "p", text: "A **spike** is a short, time-boxed piece of work whose output is knowledge, not product. It answers a single question — “can this OCR read our scans well enough?”, “can the ERP keep up at peak?” — and stops. If you find yourself answering three questions, you are running three spikes, and each needs its own signal." },
        { t: "h3", text: "Thin vertical slice and walking skeleton" },
        { t: "p", text: "Two shapes help you build small. A **thin vertical slice** cuts through every layer the question touches — input, processing, output — but only for the narrowest case. A **walking skeleton** is the thinnest end-to-end version of the system that actually runs: real connections, almost no features. Use the slice when the risk sits in one place, like extraction accuracy; use the skeleton when the risk is whether the pieces connect at all." },
        { t: "figure", fig: { kind: "split", left: { title: "Thin vertical slice", items: ["Cuts through every layer the question touches", "Input, processing, output — for the narrowest case", "Use when the risk sits in one place, like extraction accuracy"] }, right: { title: "Walking skeleton", items: ["The thinnest end-to-end version that runs", "Real connections, almost no features", "Use when the risk is whether the pieces connect at all"] } }, caption: "Two shapes for building small. Pick by where the risk sits." },
        { t: "figure", fig: { kind: "knowledge", name: "Walking skeleton" }, caption: "The walking skeleton: the thinnest end-to-end slice that proves the path works." },
        { t: "h3", text: "The signal is set in advance" },
        { t: "p", text: "The success signal is the line between “held” and “didn’t hold”, written before the run. After the result is in, the temptation to reinterpret it is strong: 84% is “basically” 85%; the failures were “unusual” documents. Don’t. If a result is borderline, say so plainly — and report it against the original signal." },
        { t: "h3", text: "Realistic data, safe environment" },
        { t: "p", text: "A prototype run on tidy test files proves nothing about messy real ones. Use realistic data — masked so it is safe — and run it in a test environment. Measure accuracy separately for each kind of input that behaves differently (for Northwind, generated PDFs and scans), and measure performance under realistic load. Load-testing tools such as k6 let you script a steady stream of requests and record throughput and errors." },
        { t: "h3", text: "Throwaway means throwaway" },
        { t: "p", text: "Prototype code skips everything that makes code fit for production: error handling, tests, security, structure. That is why it is fast, and why it must not go forward. Mark it clearly as a spike, keep it out of the product repository’s main line, and delete it — or archive it — when the write-up is done." },
        { t: "figure", fig: { kind: "hub", center: "A good spike", items: [{ label: "One question", icon: "help", text: "Answers a single question and stops; three questions are three spikes." }, { label: "Timeboxed", icon: "timer", text: "When the time runs out, you report what you know." }, { label: "Signal set in advance", icon: "flag", text: "The line between held and didn’t hold, written before the run." }, { label: "Realistic, masked data", icon: "shield", text: "Each kind of input measured separately — generated PDFs and scans." }, { label: "Test environment", icon: "science", text: "Never against production." }, { label: "Throwaway code", icon: "cancel", text: "Marked as a spike, kept out of the main line, deleted or archived after the write-up." }] }, caption: "The qualities of a spike from the key ideas. Miss one and the answer is either slow, unsafe or arguable." },
        {
          t: "terms", items: [
            { term: "Spike", def: "A short, time-boxed experiment whose output is an answer to one question, not product code." },
            { term: "Success signal", def: "The pre-agreed result that counts as the hypothesis holding — set before the run." },
            { term: "Thin vertical slice", def: "A narrow piece of work that goes through every layer the question touches, for the smallest case." },
            { term: "Walking skeleton", def: "The thinnest end-to-end version of a system that runs, used to prove the parts connect." },
            { term: "Timebox", def: "A fixed limit on the time a piece of work may take; when it runs out, you report what you know." },
            { term: "Masked data", def: "Real data with personal and sensitive values replaced, so it keeps its shape but is safe to use." },
          ],
        },

        { t: "h", text: "How to do it" },
        {
          t: "steps", items: [
            { title: "Pick the riskiest unknown", text: "From the evaluation matrix and the spike plan, pick the unknown that could most change the decision — often the one that could sink the current favourite. Restate its hypothesis and its success signal exactly as the spike plan has them. If the matrix surfaced a new unknown that isn’t in the plan, write a signal for it now, before you build anything.", tip: "Ask: if this turned out badly, would we choose differently? If not, it isn’t the riskiest unknown." },
            { title: "Build the smallest prototype", text: "Build the smallest throwaway thing that could fail — a thin vertical slice or a walking skeleton, end to end but only just. Clearly mark it as a spike. Make it runnable in the test environment, on realistic, masked data. No production credentials, no production systems.", tip: "If the answer turns up in the documentation mid-spike, stop early and record it. A spike isn’t owed its full timebox." },
            { title: "Run it and read against the signal", text: "Run the prototype and collect data, not impressions: counts, percentages, timings, error rates. Read the result against the signal set in advance. Then write the spike report: the question, the approach, the result with data, the remaining unknowns, and what it changes for the options.", tip: "Keep the raw results next to the report. Anyone should be able to recompute your headline number." },
            { title: "Decide: did the hypothesis hold?", text: "Prepare the verdict for the tech lead, who reads it: held, failed or inconclusive, and what that means for each option. Held → on to architecture options. Failed → drop or rethink the option. Inconclusive → one more time-boxed run, not five. If the spike needs more time or money, the tech lead decides." },
          ],
        },
        { t: "figure", fig: { kind: "workflow", fid: "discover.validate.prototype" }, caption: "Prototype the Riskiest Unknowns — pick, build small, run against the signal, decide." },
        { t: "callout", tone: "warn", title: "Prototype code is throwaway", text: "It proved a point; it isn’t the product. And when the timebox runs out, record what’s known and what isn’t — don’t quietly extend it." },

        { t: "h", text: "The case: Northwind" },
        { t: "callout", tone: "case", title: "Northwind", text: "SPK-1 on scans: document-AI 88%, open-source 71% — only one passes. SPK-2: the import API sustains 1,800 orders an hour." },
        { t: "p", text: "The matrix had left Northwind with a close race on generated PDFs and a big unknown on scans — the case A-01 had only guessed about. SPK-1 went straight at it: both services, the same masked inbox sample, compared line by line against what the clerks had entered." },
        { t: "figure", fig: { kind: "bars", rows: [{ label: "Document-AI service · scanned PDFs", value: 88, max: 100, note: "88%", tone: "good" }, { label: "Open-source OCR · scanned PDFs", value: 71, max: 100, note: "71%", tone: "bad" }] }, caption: "SPK-1 on scanned PDFs — the case the sandbox didn’t test. Only one option passes." },
        { t: "p", text: "Against the signal set in topic 1.2 — at least 85% of lines exact on scans — the document-AI service passes at 88% and open-source OCR fails at 71%. Nobody had to argue about it; the line was drawn before the run." },
        { t: "p", text: "SPK-2 asked a different question: can the ERP’s import API keep up at peak? The approach was a scripted import of 1,000 synthetic orders into the ERP test tenant. The signal was at least 160 orders an hour, sustained, with no errors. The API sustained 1,800 an hour." },
        { t: "figure", fig: { kind: "bars", unit: "orders/h", rows: [{ label: "Success signal (set in advance)", value: 160, max: 2000, note: "≥ 160", tone: "neutral" }, { label: "SPK-2 result · ERP import API", value: 1800, max: 2000, note: "1,800", tone: "good" }] }, caption: "SPK-2 against its signal. The import API isn’t the bottleneck — feasibility risk for import: low." },
        {
          t: "table", caption: "Northwind’s spike results, read against the signals",
          head: ["Spike", "Signal (set in advance)", "Result", "Verdict", "What it changes"],
          rows: [
            ["SPK-1 (H-01) · scans", "≥ 85% of lines exact", "Document-AI 88% · open-source OCR 71%", "Holds for document-AI only", "Open-source OCR can’t meet the scan case; it survives only with that risk named"],
            ["SPK-2 (H-02)", "≥ 160 orders/h sustained, no errors", "1,800 orders/h sustained", "Held", "Feasibility risk for import: low"],
          ],
        },
        { t: "p", text: "Notice the remaining unknowns, too. SPK-2’s report leaves one open: behaviour with malformed customer codes. That is not a reason to extend the spike — it is a line in the write-up, carried forward so it isn’t forgotten." },
        { t: "figure", fig: { kind: "template", id: "spike-results" }, caption: "Spike results — question, approach, result with data, what it changes." },

        { t: "h", text: "Working with your agent" },
        { t: "callout", tone: "agent", title: "With your agent", text: "This is where coding agents shine: a throwaway prototype in an afternoon. Give your agent the hypothesis, the signal and the timebox, and ask for the smallest thing that could fail. Read the results yourself against the signal — and delete the code when you’re done." },
        { t: "p", text: "The risk with a fast builder is that the prototype grows. An agent will cheerfully add retries, a nicer interface and a configuration file if you let it — and suddenly the spike looks like a product. Keep the brief tight, keep the scope to one question, and keep the reading of results in human hands." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Give hypothesis, signal and timebox" }, { lane: 1, label: "Build the smallest prototype that could fail", sub: "every file marked SPIKE" }, { lane: 1, label: "Output raw results, one row per item" }, { lane: 0, label: "Check: masked sample only, no production", flag: "manual" }, { lane: 1, label: "Write the report against the signal" }, { lane: 0, label: "Check the verdict against the signal as written", flag: "manual" }, { lane: 2, label: "Read the verdict", flag: "ok" }, { lane: 0, label: "Delete the code" }] }, caption: "A fast builder, kept on a short brief. The reading of results stays in human hands, and the prototype ends in the bin." },
        { t: "prompt", title: "Scaffold the spike", text: "This is a throwaway spike, not product code. Mark every file clearly as SPIKE.\nHypothesis: [paste H-## and its wording].\nSuccess signal, set in advance: [paste the signal]. Timebox: [paste].\nBuild the smallest prototype that could prove this hypothesis wrong, runnable in our test environment, on the masked sample in [folder]. No production credentials, no production systems.\nOutput raw results to a file I can inspect — one row per item tested — plus a summary of the headline number.\nDon’t add error handling, tests or features beyond what the question needs." },
        { t: "p", text: "**What to check:** that the prototype tests exactly the hypothesis and nothing more; that it reads the masked sample, not anything real; that it can’t reach production; and that the raw results let you recompute the headline number yourself." },
        { t: "prompt", title: "Write up against the signal", text: "Here are the raw results of the spike and the success signal we set before running it.\nWrite the spike report: question, approach, result with data, read against the original signal (held / failed / inconclusive), remaining unknowns, and what it changes for each option.\nIf the result is borderline, say so plainly. Do not reinterpret or adjust the signal." },
        { t: "p", text: "**What to check:** that the verdict compares the result with the signal as written, not a softened version; that the numbers in the report match the raw results; and that “what it changes” is specific — an option dropped, a risk named, an assumption closed." },

        { t: "h", text: "Common mistakes" },
        {
          t: "contrast", label: "Reading a spike result",
          bad: { title: "Impression", text: "“The open-source OCR worked pretty well on most scans — a bit of tuning and it’ll be fine.”" },
          good: { title: "Against the signal", text: "“SPK-1 on scans: open-source OCR 71% of lines exact against a signal of ≥ 85%. Failed. Document-AI 88%: held.”" },
        },
        {
          t: "pitfalls", items: [
            { trap: "The signal is moved after the result is in.", fix: "Report against the original signal; if it now seems wrong, say so separately." },
            { trap: "The prototype grows into a product.", fix: "Stop at the timebox and write up. Prototype code is throwaway." },
            { trap: "The spike runs on tidy test files.", fix: "Use realistic, masked data — and measure each kind of input separately." },
            { trap: "The prototype touches production.", fix: "Never prototype against production; use a test tenant and no production credentials." },
            { trap: "An inconclusive result earns five more runs.", fix: "One more time-boxed run; after that, the tech lead decides." },
            { trap: "The timebox runs out and nothing is reported.", fix: "Report what’s known, what isn’t, and a recommendation. Partial answers are still answers." },
          ],
        },
        { t: "figure", fig: { kind: "fishbone", effect: "A spike that doesn’t answer the question", bones: [{ label: "Signal", causes: ["Moved after the result is in"] }, { label: "Scope", causes: ["The prototype grows into a product", "An inconclusive result earns five more runs"] }, { label: "Data", causes: ["Run on tidy test files"] }, { label: "Environment", causes: ["The prototype touches production"] }, { label: "Time", causes: ["The timebox runs out and nothing is reported"] }] }, caption: "The common mistakes grouped by cause. Each one either weakens the evidence or wastes the timebox." },

        { t: "h", text: "When it goes off the path" },
        {
          t: "table", caption: "Routes out of the lesson",
          head: ["Situation", "What you do"],
          rows: [
            ["Result is borderline", "State it plainly; don’t move the signal"],
            ["Answer found in docs mid-spike", "Stop early and record it"],
            ["Inconclusive", "One more time-boxed run (rework)"],
            ["Timebox runs out", "Record what’s known and what isn’t"],
            ["Needs more time or money", "Escalate to the tech lead"],
            ["Prototype disproves the favourite", "Good: it saved the build — record it"],
            ["The prototype can’t be built at all", "That is a result: record why, and what it means for the option"],
            ["Every option fails", "Stop: back to framing — recorded in the learning log"],
          ],
        },
        { t: "figure", fig: { kind: "decide", start: "build", nodes: [{ id: "build", q: "Can the prototype be built at all?", yes: "docs", no: "cant" }, { id: "cant", result: "That is a result: record why, and what it means for the option.", tone: "neutral" }, { id: "docs", q: "Did the answer turn up in the docs mid-spike?", yes: "early", no: "time" }, { id: "early", result: "Stop early and record it.", tone: "good" }, { id: "time", q: "Has the timebox run out?", yes: "more", no: "all" }, { id: "more", q: "Does it need more time or money?", yes: "esc", no: "known" }, { id: "esc", result: "Escalate to the tech lead.", tone: "neutral" }, { id: "known", result: "Record what’s known and what isn’t.", tone: "neutral" }, { id: "all", q: "Does every option fail?", yes: "stop", no: "inc" }, { id: "stop", result: "Stop: back to framing — record it in the learning log.", tone: "bad" }, { id: "inc", q: "Is the result inconclusive?", yes: "again", no: "border" }, { id: "again", result: "One more time-boxed run (rework).", tone: "neutral" }, { id: "border", q: "Is the result borderline?", yes: "plain", no: "fav" }, { id: "plain", result: "State it plainly; don’t move the signal.", tone: "neutral" }, { id: "fav", q: "Did it disprove the favourite?", yes: "saved", no: "verdict" }, { id: "saved", result: "Good: it saved the build — record it.", tone: "good" }, { id: "verdict", result: "Write the verdict against the signal; the tech lead reads it.", tone: "good" }] }, caption: "The off-path situations as a walk-through. Notice how many of them are still results worth recording." },
        { t: "note", text: "Two measures tell you how the spikes went: how many ran inside their timebox, and how many hypotheses were disproved. A team that never disproves anything probably isn’t testing the risky parts. Spikes that changed the plan go in the learning log." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["The signal was set before running", "Results include data, not impressions", "The timebox was respected", "No prototype code goes forward"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Prototype verdict ready?", items: [
          "The unknown tested is the one that could most change the decision",
          "Every spike’s success signal was written before it ran",
          "The prototype ran on realistic, masked data in a test environment",
          "Each spike report has question, approach, result with data, remaining unknowns and what it changes",
          "Results are read against the original signal — borderline results are stated plainly",
          "Each spike stayed inside its timebox, or the tech lead agreed an extension",
          "Prototype code is marked as a spike and won’t go forward",
        ] },
        { t: "try", text: "Describe the smallest prototype that would test H-01 in one day. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.4.4 ───────────────────────────── */
    {
      id: "discover.validate.architecture", fid: "discover.validate.architecture", code: "1.4.4", title: "Sketch Architecture Options", minutes: 13,
      blocks: [
        { t: "lead", text: "A product name isn’t an architecture. Before you can compare options fairly, each surviving option needs to become a concrete sketch: the containers, the arrows between them, how it meets the targets and what it risks." },
        { t: "tldr", items: [
          "Pick the two or three options that survived the evaluation and the spikes — and say why the others dropped out.",
          "Sketch each at C4 container level, in the same notation, with protocols on the arrows.",
          "For every top quality-attribute scenario, show how each option meets it; name each option’s top risks, run cost drivers and an effort band.",
          "Options are compared, not advocated — no straw men.",
        ] },
        { t: "p", text: "This lesson turns the survivors into two or three architecture options that can be compared on the same terms. The job: *help me see the real choices side by side before I recommend one.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "“We’ll use the document-AI service” is a component choice, not a design. It doesn’t say what watches the inbox, what happens when the ERP is down, where a clerk sees an order the machine wasn’t sure about, or what crosses a trust boundary. Until those things are drawn, you can’t estimate the effort, you can’t see the risks, and you can’t compare one option with another honestly." },
        { t: "figure", fig: { kind: "hub", center: "What a product name doesn’t say", items: [{ label: "Inbox watching", icon: "inbox", text: "What watches the inbox." }, { label: "ERP down", icon: "error", text: "What happens when the ERP is down." }, { label: "Clerk review", icon: "support_agent", text: "Where a clerk sees an order the machine wasn’t sure about." }, { label: "Trust boundary", icon: "security", text: "What crosses a trust boundary." }] }, caption: "“We’ll use the document-AI service” leaves all four open. Until they are drawn you can’t estimate effort, see the risks or compare honestly." },
        { t: "p", text: "Sketching also exposes the costs a component comparison hides. A self-hosted option needs somewhere to run and someone to keep it running. A managed service has a bill that grows with volume. A new connection to an outside service is a new trust boundary that security has to look at. These are the things that turn a winning score into a losing decision months later." },
        { t: "figure", fig: { kind: "tree", root: "Costs a component comparison hides", children: [{ label: "Self-hosted option", children: [{ label: "Somewhere to run" }, { label: "Someone to keep it running" }] }, { label: "Managed service", children: [{ label: "A bill that grows with volume" }] }, { label: "New outside connection", children: [{ label: "A new trust boundary for security" }] }] }, caption: "What sketching exposes. These are the costs that turn a winning score into a losing decision months later." },
        { t: "p", text: "And sketching every option with the same care is the only protection against the most common bias in architecture work: recommending the only option you really thought about." },
        { t: "pull", text: "Options are compared, not advocated." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the last lesson of topic 1.4, and it closes the **Options Review** gate. It takes the spike results and the evaluation matrix from earlier in this topic, and the **system context diagram** from topic 1.1 — which tells you what each option has to connect to. It hands **architecture options** to topic 1.5, where feasibility, effort and risk are assessed and one option is chosen." },
        {
          t: "table", caption: "The lesson’s contract in brief",
          head: ["", "What it is"],
          rows: [
            ["Entry", "Spike results in"],
            ["Inputs", "Spike results; option evaluation matrix; system context diagram"],
            ["Output", "Two or three architecture options — each with a C4 container sketch, how it meets the targets, risks and an effort band"],
            ["Exit", "At least two real options sketched; each traced to the quality targets"],
            ["Roles", "A — Tech lead · R — Engineer · C — Architect, Security · I — Client contact"],
            ["Authority", "Tech lead accepts the options for comparison"],
            ["Policy", "Security reviews any option crossing a new trust boundary"],
            ["Timebox", "½–1 day"],
            ["Trace", "Creates ARO-## linked to OPT-##, SPK-## and QA-##"],
          ],
        },
        { t: "p", text: "Options move **Surviving options → Sketched → Traced → Reviewed**, and can be sketched in parallel." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Surviving options" }, { label: "Sketched", sub: "C4 container level" }, { label: "Traced", sub: "to the QAs" }, { label: "Reviewed", sub: "tech lead accepts", tone: "new" }] }, caption: "Each option’s path to the Options Review. Options can be sketched in parallel." },

        { t: "h", text: "What you start with" },
        { t: "p", text: "The system context diagram is the frame every sketch must fit inside. For Northwind it says: customers e-mail PDFs to a Microsoft 365 shared inbox, read through Microsoft Graph with OAuth 2.0; the new order-intake service is the only thing in scope; orders reach ERP v9 through its REST import API, with an API key, in an EU data centre; and order clerks use the ERP and a new web interface for exceptions." },
        {
          t: "table", caption: "Northwind’s system context — what every option must connect to",
          head: ["Element", "Type", "How (protocol / format)"],
          rows: [
            ["Customer", "Person (external)", "E-mail + PDF attachment"],
            ["Order clerk", "Person", "ERP client; web UI (new)"],
            ["Order-intake service", "Software system — in scope", "Graph API (read mail) · ERP import API (REST/JSON)"],
            ["Microsoft 365 shared inbox", "External system", "Microsoft Graph, OAuth 2.0"],
            ["ERP v9", "External system (vendor)", "REST import API, API key, EU data centre"],
          ],
        },
        { t: "figure", fig: { kind: "context", center: { label: "Order-intake service", sub: "in scope" }, around: [{ label: "Customer", sub: "external", type: "person", link: "E-mail + PDF attachment", dir: "in", text: "E-mails PDFs to the shared inbox." }, { label: "Microsoft 365 shared inbox", type: "external", link: "Microsoft Graph, OAuth 2.0", dir: "in", text: "The service reads mail through the Graph API." }, { label: "ERP v9", sub: "vendor, EU data centre", type: "external", link: "REST import API, API key", dir: "out", text: "Orders enter only through the import API (C-01)." }, { label: "Order clerk", type: "person", link: "ERP client; web UI (new)", dir: "both", text: "Handles exceptions in a new web interface." }] }, caption: "The frame every option must fit inside. An arrow to one of these systems that it doesn’t accept is a sketch error, not a design." },
        { t: "p", text: "From the spikes you know which options are still standing; from the matrix you know how each scored and what it still carries as unknowns. Bring all three documents into the room." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "The C4 container level" },
        { t: "p", text: "The C4 model describes software at four zoom levels: **context** (the system and the people and systems around it), **containers** (the separately running or deployable pieces — services, databases, queues, user interfaces), **components** (the parts inside a container) and **code**. Topic 1.1 gave you the context. Here you zoom in one level. At container level you can see where each option runs, how data flows, and where the risks sit — without getting lost in class design." },
        { t: "figure", fig: { kind: "knowledge", name: "C4 model" }, caption: "The C4 model’s zoom levels. Architecture options are drawn at the container level — one step in from the system context." },
        { t: "h3", text: "Same notation, every option" },
        { t: "p", text: "Draw every option in the same notation, at the same level of detail. If one option is a careful diagram with protocols on every arrow and the other is three boxes on a whiteboard, the comparison is already tilted. **Diagram-as-code** — a text format such as Mermaid or Structurizr that renders into a diagram — makes this easier: options sit side by side in version control and differences are visible." },
        { t: "h3", text: "Trace to the targets" },
        { t: "p", text: "For each top quality-attribute scenario, each option should say which part of the sketch meets it and how. “QA-2: no order is lost” is met by something — a queue, a retry policy, a store of unprocessed orders. If you can’t point to the box that meets a target, the sketch is incomplete or the option doesn’t meet it. Either way, you need to know." },
        { t: "h3", text: "Risks, run cost and effort band" },
        { t: "p", text: "Each option names its top risks — usually three is enough — and the drivers of its running cost: per-page or per-call charges, hosting, support effort. The effort band is rough (S, M, L) on purpose; real estimates come in topic 1.5. Think about failure too: how does each option behave when a dependency is down?" },
        { t: "figure", fig: { kind: "hub", center: "An architecture option", items: [{ label: "Container sketch", icon: "architecture", text: "The containers and the arrows between them, with protocols." }, { label: "Trace to targets", icon: "fact_check", text: "Which part meets each top QA scenario, and how." }, { label: "Top risks", icon: "warning", text: "Usually three is enough." }, { label: "Run cost drivers", icon: "payments", text: "Per-page or per-call charges, hosting, support effort." }, { label: "Failure behaviour", icon: "error", text: "How it behaves when a dependency is down." }, { label: "Effort band", icon: "tune", text: "Rough on purpose — S, M or L; real estimates in topic 1.5." }] }, caption: "What every option carries to topic 1.5, so the options can be compared on the same terms." },
        { t: "h3", text: "One option, or a choice inside one?" },
        { t: "p", text: "If two options differ only in a single component, they are really one option with a choice inside it. That is where **ports and adapters** help: put the replaceable part behind an interface, so changing it later doesn’t change the rest. Deciding whether two sketches are genuinely different options is a judgement — they are when the difference changes where data goes, who runs it, what it costs, or which targets it can meet." },
        { t: "figure", fig: { kind: "knowledge", name: "Ports and adapters" }, caption: "Ports and adapters: put the replaceable part behind an interface, so changing it later doesn’t change the rest." },
        {
          t: "terms", items: [
            { term: "Architecture option", def: "A concrete way to build the solution: a container sketch, how it meets each target, its top risks, its run cost drivers and an effort band." },
            { term: "Container (C4)", def: "A separately running or deployable unit — an application, a service, a database, a queue." },
            { term: "Trust boundary", def: "A line across which data passes between parties or zones with different levels of trust — for example, from your systems to a vendor’s service." },
            { term: "Effort band", def: "A rough size (S, M, L) used to compare options before real estimates exist." },
            { term: "Straw man", def: "An option included only to lose — one nobody would really choose." },
            { term: "Diagram-as-code", def: "Describing a diagram in a text format that renders it, so it can be versioned, compared and regenerated." },
          ],
        },

        { t: "h", text: "How to do it" },
        {
          t: "steps", items: [
            { title: "Pick the surviving options", text: "From the spike results and the evaluation, list the two or three options that survived, and write one line on why each of the others dropped out. Only options that survived the spikes go forward. If only one survives, sketch it alongside “improve what’s there” — so there is still a real comparison.", tip: "If every option failed the targets, stop here and go back to framing. That is a valid result." },
            { title: "Sketch each at C4 container level", text: "For each option, draw the containers, say in a line what each does, and draw the arrows between them with protocols — in the same notation for every option. Show where each container runs. Mark any new trust boundary. Keep the system context’s external systems exactly as they are: an arrow to a system that doesn’t accept that kind of call is a sketch error, not a design.", tip: "Draft it as diagram-as-code (Mermaid works well) so the options can sit side by side and be versioned." },
            { title: "Trace each to the quality targets", text: "For each option and each top quality-attribute scenario, write which part of the sketch meets it and how, citing the evaluation or the spike where you can. Then name the option’s top three risks, its run cost drivers, how it behaves when a dependency fails, and a rough effort band. If an option needs a new platform, note the run cost.", tip: "Write the trace as a table: rows are QA scenarios, columns are options. Gaps become obvious." },
            { title: "Decide: are these options worth comparing?", text: "Before the tech lead reviews them, check the options are genuinely different and genuinely viable — no straw men. A sketch that can’t be traced to the targets is redone. Two options that differ only in one component are merged into one option with a choice inside it. If an option needs platform or security approval, the tech lead escalates it. The tech lead then accepts the options for comparison." },
          ],
        },
        { t: "figure", fig: { kind: "workflow", fid: "discover.validate.architecture" }, caption: "Sketch Architecture Options — pick the survivors, sketch at container level, trace to the targets, check they’re worth comparing." },

        { t: "h", text: "The case: Northwind" },
        { t: "callout", tone: "case", title: "Northwind", text: "Option A: inbox watcher → queue → document-AI → validation → import API, with a clerk review screen. Option B swaps in self-hosted OCR." },
        { t: "p", text: "Two options survived. Option A uses the managed document-AI service; Option B runs open-source OCR and a rules engine itself. Both share the edges of the system — reading the inbox through the Graph API, queueing work so nothing is lost, validating and matching customers, and posting to the ERP import API — and both send low-confidence orders to a clerk review screen." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Inbox watcher", sub: "new", tone: "new" }, { label: "Queue", sub: "new", tone: "new" }, { label: "Document-AI", sub: "service", tone: "system" }, { label: "Validation", sub: "new · clerk review", tone: "human" }, { label: "ERP import API", sub: "existing", tone: "system" }] }, caption: "Option A at container level. Option B swaps the document-AI service for self-hosted OCR." },
        { t: "p", text: "Option B’s chain is the same at both ends: inbox watcher → queue → OCR service (a container) → rules engine → validation → ERP import API, with the review UI as in A." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Inbox watcher", tone: "new" }, { label: "Queue", tone: "new" }, { label: "OCR service", sub: "self-hosted container", tone: "risk" }, { label: "Rules engine", tone: "new" }, { label: "Validation", sub: "clerk review UI as in A", tone: "human" }, { label: "ERP import API", sub: "existing", tone: "system" }] }, caption: "Option B at container level. Both ends match Option A; the middle — who runs the extraction — is where they differ." },
        {
          t: "table", caption: "How each option meets the targets — and what it risks",
          head: ["", "Option A — managed document AI", "Option B — self-hosted OCR + rules"],
          rows: [
            ["QA-1 correctness", "96% on generated PDFs; 88% on scans (SPK-1, passes)", "93% on generated PDFs; 71% on scans (SPK-1, fails)"],
            ["QA-2 no order lost", "Queue + retry", "Queue + retry"],
            ["QA-3 latency at peak", "Well under 5 min (~6 s a page)", "Well under 5 min (~2 s a page locally)"],
            ["Top risks", "Per-page cost at peak; vendor dependency", "Scan accuracy (71%); rules upkeep"],
            ["Effort band", "M", "L"],
          ],
        },
        { t: "p", text: "Two things deserve a closer look. First, Option A sends order documents to an outside service — a new trust boundary. The EU region keeps it inside C-02, but the policy is clear: security reviews any option that crosses a new trust boundary, and the data-protection paperwork becomes something topic 1.5 has to settle." },
        { t: "p", text: "Second, are A and B really two options, or one option with a choice inside? They share most containers. What makes them genuinely different is who runs the extraction, where the documents go, how cost behaves at peak, and — after SPK-1 — whether the scan case can be met at all. That is enough to compare them as options. It is also a strong hint that the extraction step belongs behind a port, whichever is chosen." },
        { t: "figure", fig: { kind: "tree", root: "Why A and B are two options", children: [{ label: "Who runs the extraction", text: "A managed service, or self-hosted OCR and rules." }, { label: "Where the documents go", text: "Option A sends them to an outside service — a new trust boundary." }, { label: "How cost behaves at peak", text: "Per-page cost at peak is one of A’s top risks." }, { label: "Whether the scan case can be met", text: "After SPK-1: 88% passes, 71% fails." }] }, caption: "They share most containers, but differ on these four — enough to compare them as options, and a strong hint that extraction belongs behind a port." },
        { t: "figure", fig: { kind: "template", id: "architecture-options" }, caption: "Architecture options — sketch, how it meets the targets, risks, effort band." },

        { t: "h", text: "Working with your agent" },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to draw each option as diagram-as-code at container level and to fill a table of target → how it’s met. Check for hidden run costs and for arrows to systems that, per your integration inventory, don’t accept that kind of call." },
        { t: "p", text: "Drafting diagrams is tedious and agents are fast at it. The judgement — which options survived, whether two sketches are really different, whether a target is genuinely met — stays with you, the architect and the tech lead." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Share spike results, matrix and context diagram" }, { lane: 1, label: "List survivors; one line on each dropped option" }, { lane: 1, label: "Sketch each at container level", sub: "Mermaid, same notation" }, { lane: 0, label: "Check every arrow against context and integration inventory", flag: "manual" }, { lane: 1, label: "Trace to QAs; risks, run costs, effort band" }, { lane: 1, label: "Challenge the set", sub: "straw men? one-component differences?" }, { lane: 0, label: "Judge whether options are really different", sub: "with the architect" }, { lane: 2, label: "Accept the options for comparison", flag: "ok" }] }, caption: "The agent drafts diagrams and tables fast; which options survived, whether they differ, and whether a target is met stay with people." },
        { t: "prompt", title: "Sketch the survivors", text: "Here are my spike results, my option evaluation matrix and my system context diagram.\nList the options that survived and, for each that dropped out, one line on why.\nSketch each surviving option at C4 container level: the containers, what each does, where it runs, and the arrows between them with protocols. Use the same notation for every option, and give me Mermaid for each.\nMark any new trust boundary. Use only the external systems and interfaces in my context diagram — don’t invent new ones." },
        { t: "p", text: "**What to check:** that every external system and protocol matches your context diagram and integration inventory — no arrows to systems that don’t accept that call; that each option is drawn with the same care; that new trust boundaries are marked; and that nothing that failed a spike has quietly come back." },
        { t: "prompt", title: "Trace and challenge", text: "For each option, show how it meets each of my top quality-attribute scenarios (pasted below), citing the evaluation or spike results. Then list each option’s top three risks, its run cost drivers, how it behaves when a dependency fails, and a rough effort band (S / M / L).\nFinally, challenge the set: is any option a straw man? Do any two differ only in one component? Don’t recommend one — I’m comparing, not choosing yet." },
        { t: "p", text: "**What to check:** that each “how it’s met” points at a real container and real evidence; that run costs — hosting, per-call charges, support — appear for every option; and that the agent’s challenge is about viability and difference, not preference." },

        { t: "h", text: "Common mistakes" },
        {
          t: "contrast", label: "An architecture option",
          bad: { title: "A product name", text: "“Option A: use the document-AI service. Option B: something open source, probably slower.”" },
          good: { title: "A sketch you can compare", text: "“Option A: inbox watcher (Graph API) → queue → extraction (cloud doc-AI, EU) → validation and customer match → ERP import API; low confidence → clerk review UI. Meets QA-2 by queue and retry. Risks: per-page cost at peak, vendor dependency. Effort: M.”" },
        },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "“Option A: inbox watcher (Graph API) → queue → extraction (cloud doc-AI, EU) → validation and customer match → ERP import API;", label: "Containers and protocols" }, { text: " low confidence → clerk review UI.", label: "Human path" }, { text: " Meets QA-2 by queue and retry.", label: "Trace to a target", note: "A box you can point at." }, { text: " Risks: per-page cost at peak, vendor dependency.", label: "Top risks" }, { text: " Effort: M.”", label: "Effort band" }] }, caption: "A sketch you can compare, taken apart. The product-name version above has none of these parts." },
        {
          t: "pitfalls", items: [
            { trap: "The second option is a straw man nobody would choose.", fix: "Make the alternative genuinely viable or drop it — and sketch “improve what’s there” instead." },
            { trap: "Run cost is left out.", fix: "Add hosting, per-call charges and support to every option." },
            { trap: "Only the favourite is sketched properly.", fix: "Same notation, same level of detail, same care for every option." },
            { trap: "Arrows point to systems that don’t accept that kind of call.", fix: "Check every arrow against the system context diagram and the integration inventory." },
            { trap: "A target is “met” with no box to point at.", fix: "Trace each QA scenario to a specific container; if there isn’t one, redo the sketch." },
            { trap: "A new trust boundary goes unnoticed.", fix: "Mark it on the sketch; security reviews it." },
          ],
        },

        { t: "h", text: "When it goes off the path" },
        {
          t: "table", caption: "Routes out of the lesson",
          head: ["Situation", "What you do"],
          rows: [
            ["Only one option survives", "Sketch it plus “improve what’s there”"],
            ["Simple problem", "Two short options"],
            ["Options differ only in a component", "Treat it as one option with a choice inside"],
            ["An option needs a new platform", "Note the run cost"],
            ["Sketch can’t be traced to the targets", "Redo the sketch (rework)"],
            ["Option needs platform or security approval", "Escalate to the tech lead"],
            ["No option meets the targets", "Stop: back to framing — recorded in the learning log"],
          ],
        },
        { t: "figure", fig: { kind: "decide", start: "meet", nodes: [{ id: "meet", q: "Does any option meet the targets?", yes: "one", no: "stop" }, { id: "stop", result: "Stop: back to framing — record it in the learning log.", tone: "bad" }, { id: "one", q: "Does only one option survive?", yes: "improve", no: "comp" }, { id: "improve", result: "Sketch it plus “improve what’s there”.", tone: "neutral" }, { id: "comp", q: "Do the options differ only in a component?", yes: "merge", no: "trace" }, { id: "merge", result: "Treat it as one option with a choice inside.", tone: "neutral" }, { id: "trace", q: "Can each sketch be traced to the targets?", yes: "approval", no: "redo" }, { id: "redo", result: "Redo the sketch (rework).", tone: "bad" }, { id: "approval", q: "Does an option need platform or security approval?", yes: "esc", no: "platform" }, { id: "esc", result: "Escalate to the tech lead.", tone: "neutral" }, { id: "platform", q: "Does an option need a new platform?", yes: "cost", no: "accept" }, { id: "cost", result: "Note the run cost.", tone: "neutral" }, { id: "accept", result: "The tech lead accepts the options for comparison.", tone: "good" }] }, caption: "The routes out of the last lesson of the topic. Only options that can be traced to the targets reach topic 1.5." },
        { t: "callout", tone: "warn", title: "Compare, don’t advocate", text: "If you only sketched one option properly, you haven’t compared anything. Give the option you don’t prefer the same care as the one you do." },
        { t: "note", text: "The lesson’s measure is simple: are the options traced to every top QA? Options nobody expected at the start of the topic go in the learning log — they are often the most useful thing topic 1.4 produces." },

        { t: "h", text: "What good looks like" },
        { t: "good", items: ["Each option is sketched at C4 container level", "Each traces to the quality targets", "Each names its top risks", "Options are compared, not advocated"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Options ready for review?", items: [
          "Only options that survived the spikes are sketched, and dropped ones have a reason",
          "At least two genuinely viable options — no straw men",
          "Each option is at C4 container level, in the same notation, with protocols on the arrows",
          "Every arrow to an external system matches the context diagram and integration inventory",
          "Each option shows how it meets every top quality-attribute scenario",
          "Each option names its top risks, run cost drivers and an effort band",
          "New trust boundaries are marked and sent to security",
          "The tech lead has accepted the options for comparison",
        ] },
        { t: "try", text: "Sketch option A for the order-intake case as a list of containers and the arrows between them. Then do the same for your own project." },
      ],
    },
  ],
};
